def normalize(raw):
    raw = raw.strip()
    if raw.startswith("```json\n") and raw.endswith("```"):
        return raw[8:-3].strip()
    if raw.startswith("```\n") and raw.endswith("```"):
        return raw[4:-3].strip()
    return raw

